def flatten(xs):
    '''Recursively flatten nested lists.

    BUG: base case for empty list returns ``None`` instead of ``[]``.
    '''
    if not xs:
        return []
    head, *tail = xs
    if isinstance(head, list):
        return flatten(head) + flatten(tail)
    return [head] + flatten(tail)

