def pairs(iterable):
    '''Yield consecutive overlapping pairs (a,b), (b,c), ...

    Fix: Materialize the iterable once and then zip xs against xs[1:].
    '''
    xs = list(iterable)
    return list(zip(xs, xs[1:]))

